// Why Code: generates realistic demo rows with RELATIVE dates (today / tomorrow / last month)
// so the seed works no matter when it's run. Clear the Rota tab first if re-seeding.
const tz = 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const pad = (n) => String(n).padStart(2, '0');
const hhmm = (dt) => pad(dt.hour) + ':' + pad(dt.minute);
const token = () => 'tok-' + Math.random().toString(36).slice(2, 8) + '-' + Date.now().toString(36);
const today = now.toFormat('yyyy-MM-dd');
const tomorrow = now.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const inSixDays = now.plus({ days: 6 }).toFormat('yyyy-MM-dd');
const demoStart = now.plus({ hours: 3, minutes: 5 }).startOf('minute');
const demoEnd = demoStart.plus({ hours: 12 });
const octDay1 = now.minus({ months: 1 }).startOf('month');
const oct1 = octDay1.set({ day: 3 }).toFormat('yyyy-MM-dd');
const oct2 = octDay1.set({ day: 11 }).toFormat('yyyy-MM-dd');
const oct3 = octDay1.set({ day: 19 }).toFormat('yyyy-MM-dd');
const rows = [];
let seq = 1000;
const add = (shiftId, date, startTime, endTime, ward, role, req, staffId, staffName, email, tg, status) => {
  seq += 1;
  rows.push({ shiftId, date, startTime, endTime, ward, role, requiredCount: req,
    staffId, staffName, email, telegramChatId: tg,
    assignmentId: 'ASG-' + seq, status, confirmToken: token(),
    reminder1dSent: '', reminder2hSent: '', escalation3hSent: '', understaffedFlag: '' });
};
// --- THE 3-HOUR DEMO: a shift starting in ~3h05m, nobody confirmed yet (2 required)
add('SHIFT-DEMO-01', today, hhmm(demoStart), hhmm(demoEnd), 'ICU', 'Nurse', 2, 'STF-004', 'Ngozi Eze', 'ngozi.eze@example.com', '100000004', 'PENDING');
add('SHIFT-DEMO-01', today, hhmm(demoStart), hhmm(demoEnd), 'ICU', 'Nurse', 2, 'STF-005', 'Kemi Adeyemi', 'kemi.adeyemi@example.com', '100000005', 'PENDING');
// --- tomorrow morning: one confirmed, one pending (T-1 reminder demo at 18:00)
add('SHIFT-DEMO-02', tomorrow, '07:00', '19:00', 'Ward A (Medical)', 'Nurse', 2, 'STF-001', 'Adaeze Nnamdi', 'adaeze.nnamdi@example.com', '100000001', 'CONFIRMED');
add('SHIFT-DEMO-02', tomorrow, '07:00', '19:00', 'Ward A (Medical)', 'Nurse', 2, 'STF-002', 'Fatima Bello', 'fatima.bello@example.com', '100000002', 'PENDING');
// --- tomorrow outpatient: fully covered, normal shift
add('SHIFT-DEMO-03', tomorrow, '08:00', '16:00', 'Outpatient', 'Pharmacist', 1, 'STF-007', 'Halima Sule', 'halima.sule@example.com', '100000007', 'CONFIRMED');
// --- next week: understaffed pair to flag
add('SHIFT-DEMO-04', inSixDays, '09:00', '17:00', 'Ward B (Surgical)', 'Care Assistant', 2, 'STF-009', 'Emeka Obi', 'emeka.obi@example.com', '100000009', 'PENDING');
add('SHIFT-DEMO-04', inSixDays, '09:00', '17:00', 'Ward B (Surgical)', 'Care Assistant', 2, 'STF-010', 'Chibuike Okoro', 'chibuike.okoro@example.com', '100000010', 'PENDING');
// --- last month: confirmed shifts so the monthly summary has content
add('SHIFT-DEMO-M1', oct1, '07:00', '19:00', 'Ward A (Medical)', 'Nurse', 2, 'STF-001', 'Adaeze Nnamdi', 'adaeze.nnamdi@example.com', '100000001', 'CONFIRMED');
add('SHIFT-DEMO-M2', oct2, '19:00', '07:00', 'ICU', 'Nurse', 2, 'STF-001', 'Adaeze Nnamdi', 'adaeze.nnamdi@example.com', '100000001', 'CONFIRMED');
add('SHIFT-DEMO-M3', oct3, '07:00', '15:00', 'Maternity', 'Doctor', 1, 'STF-003', 'Tunde Balogun', 'tunde.balogun@example.com', '100000003', 'CONFIRMED');
add('SHIFT-DEMO-M3', oct3, '07:00', '15:00', 'Maternity', 'Doctor', 1, 'STF-005', 'Kemi Adeyemi', 'kemi.adeyemi@example.com', '100000005', 'CONFIRMED');
return rows.map((r) => ({ json: r }));
